(170, 1, '2025-06-29 11:58:40', '2025-06-29 14:58:40', '/*\n * Post CSS: start\n */\n.ast-separate-container .ast-single-related-posts-container {\n	border-top:1px solid var(--ast-global-color-3);\n}\n\n.post-navigation {\n	display:none;\n}\n/*\n * Post CSS: end\n */\n\n.cnt-image {\n	display:block;\n	margin:0 auto!important;\n	width:150px!important;\n}\n\n.form-footer .wpcf7-response-output {\n	display:none;\n}\n\n/*\n * snippet_list_authors: start\n */\n.authors-list .items {\n	display:flex;\n	overflow-x: auto;\n	list-style:none;\n	gap:20px;\n	max-width:100%;\n	justify-content:center;\n}\n\n.authors-list li {\n	width:100px;\n	flex: 0 0 auto;\n}\n\n.ast-single-post .entry-content .authors-list a {\n	text-decoration:none;\n	text-align:center;\n}\n\n.authors-list img {\n	display:block;\n	width:150px;\n	border-radius:50%;\n	margin-bottom:20px;\n}\n\n.authors-list p {\n	margin-bottom:0;\n}\n/*\n * snippet_list_authors: end\n */\n\n/*\n * Author page: start\n */\n	body .pp-multiple-authors-layout-boxed ul li {\n		padding-top:0;\n		padding-bottom:0;\n	}\n\n.ppma-page-title.page-title {\n	text-indent:-100px;\n	overflow:hidden;\n}\n/*\n * Author page: end\n */\n\n@media (min-width:768px) {\n		.ast-container #secondary .sidebar-main [id^=\"block\"].widget  {\n		padding:0 0 0 10px;\n	}\n	\n	.authors-list li {\n		width:150px;\n	}\n}\n\n@media (min-width:1024px) {\n	.cnt-image {\n		width:400px!important;\n	}	\n\n	/*\n	 * Author page: start\n	 */\n	body .pp-multiple-authors-layout-boxed ul li {\n		align-items:center;\n	}\n	.ppma-page-title.page-title {\n		text-indent:-120px;\n	}\n	/*\n	 * Author page: end\n	 */\n}', 'astra', '', 'publish', 'closed', 'closed', '', 'astra', '', '', '2025-07-12 11:10:36', '2025-07-12 14:10:36', '', 0, 'https://alura.test/astra/', 0, 'custom_css', '', 0),
