ph -->\n\n<!-- wp:paragraph -->\n<p>a karol esta vendo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Mil-folhas de paçoca: aprenda a fazer doce com massa crocante e recheio supercremoso', '', 'inherit', 'closed', 'closed', '', '158-revision-v1', '', '', '2025-07-13 10:16:55', '2025-07-13 13:16:55', '', 158, 'https://alura.test/?p=381', 0, 'revision', '', 0),
